// The header of every generated file: it names the CLI version that generated the file, so CI can
// tell a stale or hand-edited copy from the output of the pinned version (6.4, E19, A48).

/**
 * The header sentence for the files that a CLI version generates.
 * @param {string} version
 * @returns {string}
 */
export function generatedBy(version) {
  if (!version) throw new TypeError('a generated file names the CLI version that generated it')
  return `Generated by hackwin ${version}. Do not edit: hackwin setup --regenerate rewrites this file.`
}
